SELECT ((SELECT COUNT(*) FROM character_data WHERE id BETWEEN 118 AND 149) = 7 AND (SELECT COUNT(*) FROM character_data WHERE id IN (118, 125, 132, 136, 141, 145, 148) AND account_id = 86) = 7 AND (SELECT COUNT(*) FROM character_data WHERE account_id = 86) <= 12 AND (SELECT COUNT(*) FROM account WHERE id IN (87, 88)) = 0 AND (SELECT COUNT(*) FROM login_accounts WHERE id IN (86, 87)) = 0) AS applied;
